// Codex Voice OpenCode CLI plugin.
// Generated by opencode_setup.py. Keep this file dependency-free and fail open:
// a reminder must never block an OpenCode turn.
//
// OpenCode 2 loads this module through cli.json/tui.json and calls setup(ctx)
// in the server process. The context exposes ctx.event.subscribe({signal}) as
// an async iterator of {type, data} events and ctx.session.get for session
// records; both shapes have been probed defensively because the adapter may
// unwrap {data} envelopes.
import { mkdirSync, writeFileSync, renameSync } from "node:fs"
import { join } from "node:path"
import { randomUUID } from "node:crypto"

const MARKER = "codex-voice-opencode-v1"
const STATE_DIR = __CODEX_VOICE_STATE_DIR__
const ABORT_ERROR_NAMES = new Set(["MessageAbortedError", "AbortError"])

function safeText(value, limit) {
  return String(value ?? "")
    .replace(/[\u0000-\u001f\u007f]/g, " ")
    .replace(/https?:\/\/\S+/g, "[链接]")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, limit)
}

function send(event) {
  try {
    const inbox = join(STATE_DIR, "inbox")
    mkdirSync(inbox, { recursive: true, mode: 0o700 })
    const target = join(inbox, `${Date.now()}-${randomUUID()}.json`)
    const temporary = target + ".tmp"
    const body = JSON.stringify({
      action: "agent",
      source: "opencode",
      sentAt: Date.now() / 1000,
      event,
    })
    writeFileSync(temporary, body, { mode: 0o600 })
    renameSync(temporary, target)
  } catch {
    // The app may not be installed, the disk may be full, or permissions may
    // differ. Notifications are best effort and must never break OpenCode.
  }
}

function unwrapSession(result) {
  for (const item of [result, result?.data, result?.data?.info, result?.info]) {
    if (item && typeof item === "object" && typeof item.id === "string") return item
  }
  return undefined
}

// OpenCode TUI contexts render panes; this plugin only observes server events.
function isTuiContext(ctx) {
  return typeof ctx?.ui?.router?.current === "function" && typeof ctx?.data?.listen === "function"
}

async function serverSetup(ctx) {
  const noop = async () => {}
  // OpenCode probes setup() with no context during startup; a throw here
  // surfaces as a failed plugin instead of silently running unobserved.
  try {
    if (!ctx || typeof ctx.event?.subscribe !== "function" || typeof ctx.session?.get !== "function") return noop

    const sessions = new Map() // sessionID -> {title, parentID}
    const roots = new Map() // sessionID -> Boolean(isSubagent), memoized walks
    const seenPermissions = new Set()
    const seenForms = new Set()
    const lastErrors = new Map() // sessionID -> consecutive error signature

    const remember = (map, key, value) => {
      map.delete(key)
      map.set(key, value)
      while (map.size > 512) map.delete(map.keys().next().value)
    }

    // parentID stays undefined until an authoritative session.get lookup
    // provides it; event payloads may omit it and must not fake a root.
    const cacheSession = (record) => {
      if (!record || typeof record.id !== "string" || !record.id) return
      remember(sessions, record.id, {
        title: safeText(record.title, 120),
        parentID: typeof record.parentID === "string" ? record.parentID : "",
      })
    }

    const cacheTitle = (sessionID, title) => {
      if (!sessionID) return
      const known = sessions.get(sessionID)
      remember(sessions, sessionID, {
        title: safeText(title, 120) || known?.title || "",
        parentID: known?.parentID,
      })
    }

    async function lookupSession(sessionID, signal) {
      const calls = [
        [{ path: { id: sessionID } }, { signal }],
        [{ sessionID }, { signal }],
        [{ path: { id: sessionID }, signal }],
      ]
      for (const args of calls) {
        try {
          const info = unwrapSession(await ctx.session.get(...args))
          if (info) {
            cacheSession(info)
            return sessions.get(info.id)
          }
        } catch {
          if (signal?.aborted) return undefined
        }
      }
      return undefined
    }

    // Child sessions (oh-my-opencode style tools) emit their own completion
    // events; their work must not announce the root conversation as finished.
    // Unknown sessions stay quiet rather than risk a spurious completion.
    async function isSubagent(sessionID, signal) {
      const memoized = roots.get(sessionID)
      if (memoized !== undefined) return memoized
      let current = sessionID
      for (let depth = 0; depth < 32; depth++) {
        let known = sessions.get(current)
        if (!known || known.parentID === undefined) {
          known = await lookupSession(current, signal)
          if (!known) return undefined
        }
        if (!known.parentID) break
        const parentVerdict = roots.get(known.parentID)
        if (parentVerdict !== undefined) {
          remember(roots, sessionID, parentVerdict)
          return parentVerdict
        }
        current = known.parentID
      }
      remember(roots, sessionID, current !== sessionID)
      return current !== sessionID
    }

    async function titleOf(sessionID, signal) {
      const known = sessions.get(sessionID)
      if (known?.title) return known.title
      return (await lookupSession(sessionID, signal))?.title || "OpenCode 任务"
    }

    async function handle(type, data) {
      const sessionID = typeof data?.sessionID === "string" ? data.sessionID : ""
      if (type === "permission.asked") {
        const requestID = data?.id
        if (!requestID || !sessionID || seenPermissions.has(requestID)) return
        seenPermissions.add(requestID)
        send({
          action: "add",
          id: "opencode:approval:" + requestID,
          thread: sessionID,
          requestId: requestID,
          kind: "approval",
          title: await titleOf(sessionID),
          detail: "等待你在 OpenCode 中确认操作",
          delay: 1,
          source: "opencode",
        })
      } else if (type === "permission.replied" || type === "permission.v2.replied") {
        const requestID = data?.requestID ?? data?.permissionID ?? data?.id
        if (!requestID) return
        seenPermissions.delete(requestID)
        send({
          action: "resolve_request",
          thread: sessionID,
          requestId: requestID,
          source: "opencode",
        })
      } else if (type === "form.created") {
        const form = data?.form
        if (!form?.id || !form?.sessionID || seenForms.has(form.id)) return
        seenForms.add(form.id)
        send({
          action: "add",
          id: "opencode:question:" + form.id,
          thread: form.sessionID,
          requestId: form.id,
          kind: "question",
          title: await titleOf(form.sessionID),
          detail: safeText(form.title, 120) || "需要你补充输入",
          source: "opencode",
        })
      } else if (type === "form.replied" || type === "form.cancelled") {
        if (!data?.id) return
        seenForms.delete(data.id)
        send({
          action: "resolve_request",
          thread: sessionID,
          requestId: data.id,
          source: "opencode",
        })
      } else if (type === "session.execution.started") {
        if (!sessionID) return
        // A new turn means the human is back at the keyboard, so stale cards
        // from the previous turn can retire. Auto-continued chains also pass
        // here; OpenCode's stream carries no composer attribution to tell
        // them apart, matching how the Codex observer behaved before it
        // learned turn triggers.
        send({ action: "resolve_thread", thread: sessionID, reason: "任务已继续", source: "opencode" })
      } else if (type === "session.execution.succeeded") {
        if (!sessionID || (await isSubagent(sessionID)) !== false) return
        const turn = typeof data?.messageID === "string" ? data.messageID : ""
        send({
          action: "add",
          id: "opencode:result:" + sessionID + ":" + (turn || Date.now()),
          thread: sessionID,
          turn,
          kind: "result",
          title: await titleOf(sessionID),
          detail: "这一轮已经完成",
          source: "opencode",
        })
      } else if (type === "session.execution.failed") {
        if (!sessionID || (await isSubagent(sessionID)) !== false) return
        const error = data?.error
        const name = safeText(error?.name, 60)
        if (ABORT_ERROR_NAMES.has(name)) {
          send({ action: "resolve_thread", thread: sessionID, reason: "本轮已取消", source: "opencode" })
          return
        }
        const message = safeText(error?.message, 140)
        const signature = name + "\u0000" + message
        if (lastErrors.get(sessionID) === signature) return
        remember(lastErrors, sessionID, signature)
        send({
          action: "add",
          id: "opencode:blocked:" + sessionID + ":" + Date.now(),
          thread: sessionID,
          kind: "blocked",
          title: await titleOf(sessionID),
          detail: message || name || "这一轮执行失败，需要你查看",
          source: "opencode",
        })
      } else if (type === "session.execution.interrupted") {
        if (!sessionID) return
        lastErrors.delete(sessionID)
        send({ action: "resolve_thread", thread: sessionID, reason: "本轮已取消", source: "opencode" })
      } else if (type === "session.deleted") {
        const info = data?.info && typeof data.info === "object" ? data.info : data
        const thread = typeof info?.id === "string" ? info.id : sessionID
        if (!thread) return
        send({ action: "resolve_thread", thread, reason: "会话已删除", source: "opencode" })
      } else if (type === "session.created" || type === "session.updated") {
        const info = data?.info && typeof data.info === "object" ? data.info : data
        if (info) cacheTitle(info.id || sessionID, info.title)
      }
    }

    const controller = new AbortController()
    const consuming = (async () => {
      for await (const input of ctx.event.subscribe({ signal: controller.signal })) {
        if (controller.signal.aborted) break
        try {
          await handle(String(input?.type || ""), input?.data ?? input?.properties ?? {})
        } catch {
          // One malformed event must not kill the subscription.
        }
      }
    })().catch(() => {})

    return async () => {
      try {
        controller.abort()
        await consuming
      } catch {}
    }
  } catch {
    return noop
  }
}

export default {
  id: "codex-voice.notifications",
  setup: async (ctx) => (isTuiContext(ctx) ? serverSetup({}) : serverSetup(ctx)),
}
